use std::{fs,path::Path};
fn names(s:&str)->Result<Vec<String>,String>{let mut v=vec![];for l in s.lines().filter(|l|l.starts_with('\'')){let(n,a)=l.strip_prefix('\'').unwrap().split_once("' ").ok_or("format")?;if a!="does not depend on any axioms"{let ax=a.strip_prefix("depends on axioms: [").and_then(|x|x.strip_suffix(']')).ok_or("axiom format")?;if !ax.split(", ").all(|x|["propext","Classical.choice","Quot.sound"].contains(&x)){return Err("forbidden".into())}}v.push(n.to_owned())}Ok(v)}
fn main(){let p=std::env::args().nth(1).unwrap();let p=Path::new(&p);assert_eq!(fs::read_to_string(p.join("logs/ReviewerControls.exit")).unwrap().trim(),"0");let s=fs::read_to_string(p.join("logs/ReviewerControls.stdout")).unwrap();let expected=["StrictReviewer.empty_support_rejected","StrictReviewer.stored_zero_nonnormal","StrictReviewer.decoded_zero_not_empty","StrictReviewer.zero_residual_excluded"];assert_eq!(names(&s).unwrap(),expected);println!("reviewer controls and exact axiom inventory accepted");}
